import React, { useState, useEffect } from "react";
import styled, { keyframes } from "styled-components";

const NAVBAR_HEIGHT = 70;

const slideIn = keyframes`
  from {
    transform: translateX(100%);
  }
  to {
    transform: translateX(0);
  }
`;

const Backdrop = styled.div`
  position: fixed;
  top: ${NAVBAR_HEIGHT}px;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 99;
`;

const Button = styled.button`
  padding: 12px 22px;
  background: linear-gradient(135deg, #ff416c, #ff4b2b);
  color: #fff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  box-shadow: 0 6px 20px rgba(255, 65, 108, 0.5);
  transition: all 0.3s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(255, 65, 108, 0.6);
  }
`;

const Panel = styled.div`
  position: fixed;
  top: ${NAVBAR_HEIGHT}px;
  right: 0;
  width: 420px;
  max-width: 90vw;
  height: calc(100vh - ${NAVBAR_HEIGHT}px);
  background: ${({ theme }) =>
    theme?.mode === "dark" ? "#121212" : "#ffffff"};
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.35);
  padding: 24px;
  z-index: 100;
  overflow-y: auto;
  animation: ${slideIn} 0.3s ease forwards;
`;

const PanelImage = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;

  img {
    width: 50%;
    border-radius: 12px;
  }
`;

export const PanelTitle = styled.h2`
  margin: 10px 0;
`;

export const PanelText = styled.p`
  line-height: 1.6;
  margin-top: 10px;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 15px;
  right: 20px;
  background: none;
  border: none;
  font-size: 28px;
  cursor: pointer;
  color: #ff416c;
`;


const SidePanel = ({ open, onClose, book }) => {
  const [addedBooks, setAddedBooks] = useState({});

  const addtoLib = (book) => {
    if (addedBooks[book.title]) return;
    setAddedBooks((prev) => ({ ...prev, [book.title]: true }));
    let myBooks = JSON.parse(localStorage.getItem("books")) || {};
    myBooks[book.title] = book;
    localStorage.setItem("books", JSON.stringify(myBooks));
  };

  const removeLib = (title) => {
  const storedBooks = JSON.parse(localStorage.getItem("books")) || {};
  delete storedBooks[title];
  localStorage.setItem("books", JSON.stringify(storedBooks));

  setAddedBooks((prev) => {
    const updated = { ...prev };
    delete updated[title];
    return updated;
  });
};

useEffect(() => {
  const storedBooks = JSON.parse(localStorage.getItem("books")) || {};
  const mapped = {};
  Object.keys(storedBooks).forEach((title) => {
    mapped[title] = true;
  });
  setAddedBooks(mapped);
}, []);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "auto";
    return () => (document.body.style.overflow = "auto");
  }, [open]);

  if (!open) return null;

  return (
    <>
      <Backdrop onClick={onClose} />
      <Panel>
        <CloseButton onClick={onClose}>×</CloseButton>
        <PanelImage>
              <img
               src={book?.thumbnail}
                alt={book?.title}
              />
        </PanelImage>
        <h2>{book?.title}</h2>
        <p><strong>Author:</strong> {book?.author}</p>
        <p style={{ marginTop: "15px" }}>
        {book?.description}
        </p>
        {addedBooks[book?.title] ? (
          <Button
            style={{ marginTop: "20px", width: "100%" }}
            onClick={() => removeLib(book.title)}
          >
            Remove from Library
          </Button>
        ) : (
          <Button
            style={{ marginTop: "20px", width: "100%" }}
            onClick={() => addtoLib(book)}
          >
          Add to Library
          </Button>
        )}
      </Panel>
    </>
  );
};

export default SidePanel;
